import React, { useEffect, useState } from "react";
import axios from "axios";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

function Result() {
  const [chartData, setChartData] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");

    axios
      .get("http://localhost:8080/api/result/1", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
      .then((res) => {
        const labels = res.data.map((r) => r.candidate);
        const votes = res.data.map((r) => r.votes);

        setChartData({
          labels,
          datasets: [
            {
              label: "Votes",
              data: votes,
              backgroundColor: [
                "#4CAF50",
                "#2196F3",
                "#FF9800",
                "#E91E63",
              ],
            },
          ],
        });
      });
  }, []);

  return (
    <div style={{ width: "600px", margin: "auto" }}>
      <h2>Election Result</h2>

      {chartData && (
        <Bar
          data={chartData}
          options={{
            responsive: true,
            plugins: {
              legend: { position: "top" },
              title: { display: true, text: "Election Result" },
            },
          }}
        />
      )}
    </div>
  );
}

export default Result;
